{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "Suvorexant had a mean absolute oral bioavailability of 82% under fasted conditions, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Zalcitabine had an absolute oral bioavailability of 80% under fasting conditions in patients with advanced HIV infection, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Lurasidone had a bioavailability of 10% in the fasted state, arguing against F >= 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most transferred evidence, including fasted-state absolute bioavailability values, supports high oral bioavailability at the F >= 20% threshold. One fasted-state low-F record is outweighed by multiple high-F records with comparable assay-transfer scores.",
  "evidence_gaps": [
    "Molecule 2 combines records for different compounds (brigatinib and GSK1322322), creating a provenance conflict that prevents reliable use of that evidence.",
    "Molecule 8 provides only qualitative 'good' oral bioavailability without a threshold-relevant numeric value.",
    "Many supportive records are not explicitly fasted, so fasted-state transferability is best established by only a subset of the evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

